import {CASE_SAVE,initialCase,restoreCase,caseAction,caseReady,caseHint} from './photo-case-engine.js?v=131';
const app=document.querySelector('#case-app');
app.innerHTML=`<header><div><div class="brand">AFTERLIGHT PHOTO STUDIO</div><h1>마지막 컷의 사진관</h1></div><div class="header-actions"><button id="journal">기록 <span id="count">0</span>/3</button><button id="help" aria-label="현재 단계 힌트">?</button></div></header><div class="shell"><aside class="brief"><span class="eyebrow">REQUEST 01 · TOKYO</span><h2>빈자리의 주인</h2><p>“내일 이 건물이 철거돼요.<br>아버지가 늘 앉던 자리에서<br>가게의 마지막 사진을 찍어 주세요.”</p><p class="signature">미나미 사진관 · 딸, 하루</p><div class="rule"></div><div class="steps"><span id="step-compare">사진 비교</span><span id="step-read">사연 발견</span><span id="step-photo">마지막 한 컷</span></div><p class="small">옛 사진은 답을 알려 주지 않아요.<br>지금 남은 흔적과 함께 읽어 보세요.</p><a class="return" href="index.html?chapter=tokyo&v=121">기존 여행 이야기로 돌아가기 ↗</a></aside><section class="game-panel" aria-label="미나미 사진관 조사"><div class="scene-wrap"><canvas class="scene" id="scene" width="1536" height="1360" aria-label="사진관. 의자를 왼쪽으로 옮기고 편지와 바닥 흔적을 살펴볼 수 있습니다."></canvas><div class="scene-top"><span class="scene-label">MINAMI · THE LAST AFTERNOON</span><button id="detail-toggle">사물 위치 보기</button></div><div class="scene-targets" id="targets" hidden><button class="target" data-object="chair" style="left:64%;top:78%" aria-label="의자 옮기기">의자</button><button class="target" data-object="lamp" style="left:29%;top:33%" aria-label="스탠드 켜거나 끄기">빛</button><button class="target" data-object="letter" style="left:63%;top:87%" aria-label="의자 아래 편지 읽기">편지</button><button class="target" data-object="mark" style="left:75%;top:92%" aria-label="바닥의 의자 흔적 살펴보기">흔적</button></div><div class="scene-bottom"><span id="scene-caption">종이 끝이 의자 아래에 살짝 보여요.</span></div><section class="comparison" id="comparison" hidden aria-label="옛 사진 비교"><header><strong>1988년의 사진을 겹쳐 보기</strong><button id="compare-close">비교 닫기</button></header><div class="compare-view" id="compare-view"><canvas id="compare-canvas" width="1536" height="1360" aria-label="옛 사진을 좌우로 밀어 현재 선반과 맞추세요"></canvas></div><div class="compare-controls"><span aria-hidden="true">↔</span><input id="align" type="range" min="-180" max="180" value="150" aria-label="옛 사진 좌우 위치"><button id="match">겹침 확인</button></div><p class="compare-status" id="compare-status">사진을 밀어 선반 기둥을 맞춰요. 두 의자의 위치도 살펴보세요.</p></section></div><nav class="tools" aria-label="조사 도구"><button id="compare">사진 비교</button><button id="back-photo">사진 뒤집기</button><button id="move-chair">의자 옮기기</button><button id="lamp">빛 켜기</button><button id="read-letter" hidden>바닥 편지</button><button id="read-mark" hidden>의자 흔적</button><button id="camera">마지막 촬영</button></nav><p class="status" id="status" role="status" aria-live="polite">사진을 비교하거나 사물을 직접 움직여 보세요.</p><div class="footer-note"><span id="save-status">이 기기에 자동 저장 · 시간 제한 없음</span><span>첫 의뢰 체험 · 0.13.1</span></div></section></div><section class="modal" id="modal" hidden role="dialog" aria-modal="true" aria-label="의뢰 살펴보기"><div class="sheet" id="sheet"></div></section>`;
const $=id=>document.getElementById(id),canvas=$('scene'),c=canvas.getContext('2d'),cmp=$('compare-canvas'),cc=cmp.getContext('2d');
let state=initialCase(),storage=true;try{state=restoreCase(JSON.parse(localStorage.getItem(CASE_SAVE)));}catch{}let assets={},offset=state.aligned?0:150,compareOpen=false,hint=0,lastHint='',modalFocus=null,photoURL=null,drag=null,chairVisual=state.chair,anim=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const evidenceCount=()=>Number(state.back)+Number(state.letter)+Number(state.mark);
function say(text){$('status').textContent=text;}
function dispatch(e){const r=caseAction(state,e);if(!r.ok){say({alignment:'선반의 세로선이 아직 어긋나 있어요.',covered:'의자를 왼쪽으로 옮기면 아래를 볼 수 있어요.',compare:'먼저 옛 사진과 현재 공간의 구도를 맞춰 보세요.',dark:'빛을 켜면 바닥의 옅은 흔적이 보여요.',evidence:'사진 뒷면, 편지와 바닥 흔적을 함께 살펴봐요.',reason:'사진 뒷면의 문장과 편지의 여러 이름을 다시 비교해 보세요.',unfinished:'기록에서 빈자리의 주인을 알아낸 뒤 구도를 골라요.'}[r.reason]||'아직 그 행동을 할 수 없어요.');return false;}state=r.state;try{localStorage.setItem(CASE_SAVE,JSON.stringify(state));}catch{storage=false;}update();return true;}
function update(){
 $('count').textContent=evidenceCount();$('step-compare').classList.toggle('done',state.aligned);$('step-read').classList.toggle('done',!!state.answer);$('step-photo').classList.toggle('done',state.shot);
 $('lamp').textContent=state.lamp?'빛 끄기':'빛 켜기';$('lamp').setAttribute('aria-pressed',String(state.lamp));$('read-letter').hidden=state.chair>710;$('read-mark').hidden=!(state.chair<=710&&state.lamp&&state.aligned);
 $('camera').textContent=state.shot?'완성한 사진책':'마지막 촬영';$('scene-caption').textContent=state.shot?'이 가게의 마지막 오후를 남겼어요.':state.answer?'두 자리의 사연을 알았어요. 이제 어떤 모습을 남길까요?':state.chair<=710?'의자가 비켜난 자리에 편지와 옅은 자국이 남아 있어요.':'종이 끝이 의자 아래에 살짝 보여요.';
 if(!storage)$('save-status').textContent='저장이 차단됐어요 · 이 창에서 이어서 플레이할 수 있어요';
 draw(c);positionTargets();if(compareOpen)drawCompare();
}
function paper(ctx,x,y,w,h){ctx.save();ctx.translate(x,y);ctx.rotate(-.1);ctx.shadowColor='#3a2c2444';ctx.shadowBlur=6;ctx.fillStyle='#dcd0ad';ctx.fillRect(-w/2,-h/2,w,h);ctx.shadowBlur=0;ctx.strokeStyle='#9e8f6d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w/2,-h/2);ctx.lineTo(0,4);ctx.lineTo(w/2,-h/2);ctx.stroke();ctx.restore();}
function chair(ctx,x,y=930,scale=1){ctx.save();ctx.fillStyle='#43362429';ctx.beginPath();ctx.ellipse(x+150*scale,y+305*scale,132*scale,22*scale,0,0,Math.PI*2);ctx.fill();ctx.drawImage(assets.chair,x,y,310*scale,310*scale);ctx.restore();}
function mark(ctx,old=false){ctx.save();ctx.strokeStyle=old?'#61513c90':'#846c4455';ctx.lineWidth=4;for(const [x,y]of[[1080,1224],[1230,1210],[1055,1280],[1245,1263]]){ctx.beginPath();ctx.ellipse(x,y,13,5,-.12,0,Math.PI*2);ctx.stroke();}ctx.restore();}
function draw(ctx,{old=false,photo=false,choice=null}={}){
 if(!assets.room||!assets.chair)return;
 ctx.clearRect(0,0,1536,1360);ctx.drawImage(assets.room,0,0,1536,1360);
 if(old){ctx.fillStyle='#b29b6126';ctx.fillRect(0,0,1536,1360);chair(ctx,590);chair(ctx,1000);
  // The same visible props described by the photograph's reverse.
  ctx.save();ctx.translate(730,1120);ctx.rotate(-.04);ctx.fillStyle='#514334';ctx.shadowColor='#33291e55';ctx.shadowBlur=5;ctx.beginPath();ctx.roundRect(-48,-22,96,58,9);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#66533b';ctx.lineWidth=6;ctx.beginPath();ctx.arc(0,-20,33,Math.PI,0);ctx.stroke();ctx.strokeStyle='#b29b72';ctx.lineWidth=2;ctx.strokeRect(-38,-13,76,38);ctx.restore();
  ctx.save();ctx.translate(1150,1118);ctx.rotate(-.07);ctx.fillStyle='#dad0b1';ctx.shadowColor='#55442b44';ctx.shadowBlur=5;ctx.beginPath();ctx.roundRect(-82,-19,164,44,14);ctx.fill();ctx.restore();}

 else{
  if(!state.letter)paper(ctx,975,1190,115,71);if(state.lamp&&state.aligned)mark(ctx);
  const x=photo?(choice==='space'?590:1000):chairVisual;chair(ctx,x);
 }
 // Preserve the actual scene perspective. A soft local pool, never a hard triangle.
 if(!old&&state.lamp){const glow=ctx.createRadialGradient(630,690,25,780,1010,450);glow.addColorStop(0,'#ffdc8120');glow.addColorStop(1,'#ffe9a000');ctx.fillStyle=glow;ctx.fillRect(170,350,1150,970);}
 else if(!old){ctx.fillStyle='#28372f20';ctx.fillRect(0,0,1536,1360);}
 if(!photo&&!old){ctx.fillStyle='#fcf7e119';ctx.fillRect(0,0,1536,1360);}
}
function drawCompare(){draw(cc);cc.save();cc.translate(offset,0);cc.globalAlpha=.5;const tmp=document.createElement('canvas');tmp.width=1536;tmp.height=1360;draw(tmp.getContext('2d'),{old:true});cc.drawImage(tmp,0,0);cc.restore();cc.strokeStyle='#f8f0dacc';cc.lineWidth=4;cc.strokeRect(610+offset,48,320,810);cc.setLineDash([12,12]);cc.strokeStyle='#344b40aa';cc.strokeRect(610,48,320,810);cc.setLineDash([]);$('compare-status').textContent=state.aligned&&Math.abs(offset)<54?'구도가 맞았어요. 옛 사진에는 의자가 두 개, 지금은 하나예요.':Math.abs(offset)<54?'선반의 선이 가까워졌어요. 겹침 확인을 눌러요.':'사진을 좌우로 밀어 선반 기둥 두 개를 겹쳐요.';}
function show(title,html,{closable=true}={}){modalFocus=document.activeElement;$('sheet').innerHTML=(closable?'<button class="close" data-action="close" aria-label="닫기">×</button>':'')+`<span class="eyebrow">AFTERLIGHT · REQUEST 01</span><h2>${title}</h2>${html}`;$('modal').hidden=false;const first=$('sheet').querySelector('button,a,input');first?.focus();}
function close(){ $('modal').hidden=true;modalFocus?.focus?.();}
function inspectBack(){dispatch({type:'back'});show('사진 뒤에 남은 말',`<div class="note">“한 장 찍고, 한숨 돌리고.<br>처음 보는 얼굴도 편히 앉다 가기를.”<br><br><small>1988 · 미나미 사진관</small></div><p>같은 자리에서 찍은 사진이에요.<br>왼쪽 의자에는 낡은 카메라 가방이, 오른쪽에는 작은 방석이 놓여 있었어요.</p><div class="actions"><button class="primary" data-action="close">가게 다시 보기</button></div>`);}
function inspectLetter(){if(!dispatch({type:'letter'}))return;show('의자 아래의 봉투',`<p>버려진 편지가 아니었어요. 하루가 모아 둔 감사 인사였어요.</p><div class="note">“비를 피하러 들어갔다가 사진도 한 장 남겼네요.” — 마키<br><br>“제 차례가 아니어도 쉬어 가라던 말, 기억해요.” — 켄<br><br>“아저씨와 나란히 앉아 사진을 기다리던 오후가 좋아요.” — 유이</div><p>보낸 사람은 서로 달라요. 세 편지 모두 이 사진관의 의자를 기억하고 있어요.</p><div class="actions"><button data-action="journal">기록에서 함께 보기</button><button class="primary" data-action="close">봉투 내려놓기</button></div>`);}
function inspectMark(){if(!dispatch({type:'mark'}))return;show('사라진 의자의 자리',`<p>스탠드 빛을 비추자 네 개의 옅은 다리 자국이 보여요. 옛 사진의 오른쪽 의자와 같은 자리예요.</p><div class="note">의자는 사라졌지만<br>그 자리를 지운 흔적은 없어요.</div><p>하루가 덧붙인 메모: “오른쪽 의자는 새 작업실로 먼저 보냈어요. 아버지는 마지막까지 두 자리를 비워두지 않으셨어요.”</p><div class="actions"><button class="primary" data-action="journal">모은 기록 연결하기</button></div>`);}
function journal(message=''){
 let html=`<p>세 기록을 함께 읽고, 오른쪽 빈자리의 주인을 생각해 보세요.</p>`;
 for(const [key,title,text]of[['back','사진 뒷면','“처음 보는 얼굴도 편히 앉다 가기를.” 왼쪽은 카메라 가방, 오른쪽은 방석.'],['letter','여러 이름의 감사 편지','비를 피한 마키, 쉬어 간 켄, 사진을 기다린 유이. 모두 같은 의자를 기억한다.'],['mark','오른쪽 바닥의 흔적','옛 사진의 의자 위치와 같다. 의자는 이미 새 작업실로 옮겼다.']])html+=`<div class="evidence"><strong>${state[key]?'✓':'○'} ${title}</strong><p>${state[key]?text:'아직 살펴보지 않았어요.'}</p></div>`;
 if(state.answer)html+='<div class="note">빈자리는 이곳을 찾아온 손님들을 위한 자리였어요.<br>사진을 기다리는 시간도, 누군가에게는 쉬어 가는 오후였네요.</div><div class="actions"><button class="primary" data-action="camera">마지막 사진 구도 고르기</button><button data-action="close">더 둘러보기</button></div>';
 else if(evidenceCount()===3)html+='<div class="options"><button data-answer="family">돌아오지 않는 가족을 기다리는 자리</button><button data-answer="visitors">이곳에 찾아와 쉬어 가는 손님들의 자리</button><button data-answer="sale">팔기 위해 전시해 둔 의자의 자리</button></div>';
 else html+='<div class="actions"><button class="primary" data-action="close">남은 흔적 찾아보기</button></div>';
 if(message)html+=`<p class="toast" role="status">${message}</p>`;show('빈자리는 누구의 자리였을까요?',html);
}
function capture(choice=state.choice){const out=document.createElement('canvas');out.width=1536;out.height=1360;draw(out.getContext('2d'),{photo:true,choice});return out.toDataURL('image/jpeg',.9);}
function camera(){if(state.shot){ending();return;}if(!caseReady(state)){journal('세 기록을 연결하면 마지막 구도를 고를 수 있어요.');return;}show('마지막 오후를 어떻게 남길까요?',`<p>두 자리를 기억하는 방법은 하나만 있지 않아요.<br>이 선택에는 틀린 답이 없어요.</p><div class="options"><button data-choice="space" ${state.choice==='space'?'aria-pressed="true"':''}>빈자리도 함께 남기기<span>왼쪽 의자와 오른쪽의 빈 공간. 이곳을 거쳐 간 사람들을 담아요.</span></button><button data-choice="window" ${state.choice==='window'?'aria-pressed="true"':''}>의자를 창가로 옮기기<span>빛이 드는 오른쪽 자리. 새 작업실로 향하는 오후를 담아요.</span></button></div>${state.choice?`<img class="preview" src="${capture()}" alt="${state.choice==='space'?'왼쪽 의자와 오른쪽 빈자리':'창가 오른쪽으로 옮긴 의자'}의 촬영 미리보기"><p class="caption">${state.choice==='space'?'누구든 앉다 갈 수 있던 자리':'다음 오후에도, 빛이 드는 곳에서'}</p><div class="actions"><button class="primary" data-action="shoot">사진 찍기</button><button data-action="close">가게 다시 보기</button></div>`:''}`);}
function ending(){photoURL=capture();const space=state.choice==='space';show('첫 의뢰를 마쳤어요',`<span class="eyebrow">PHOTO BOOK · 01 / 빈자리의 주인</span><img class="preview" src="${photoURL}" alt="내가 선택한 마지막 가게 사진"><p class="caption">${space?'누구든 앉다 갈 수 있던 자리':'다음 오후에도, 빛이 드는 곳에서'}</p><div class="note">${space?'“빈자리까지 찍어 주셨네요. 아버지는 그 자리를 보시고 제일 오래 웃으셨어요.”':'“의자를 창가로 옮기셨네요. 새 작업실에도 이렇게 놓아 보겠대요.”'}<br><br>“철거되는 건 가게지만, 사진관은 계속될 거예요. 다음엔 새 주소로 찾아와 주세요.”<br><small>— 하루의 답장</small></div><div class="actions"><a class="file-button" href="${journalImage()}" download="afterlight-case01.jpg">사진책 저장하기</a><button data-action="close">가게에 잠시 머물기</button></div><p class="journal-note">다음 의뢰 예고 · 잘못 배달된 생일 사진<br>이번 체험은 여기까지예요. 다음 의뢰는 아직 준비 중이에요.</p><div class="actions"><button data-action="replay">다른 시선으로 다시 촬영</button></div>`);}
function journalImage(){const out=document.createElement('canvas');out.width=1200;out.height=1450;const g=out.getContext('2d');g.fillStyle='#f5f0e2';g.fillRect(0,0,1200,1450);g.fillStyle='#435243';g.font='22px Georgia';g.fillText('AFTERLIGHT PHOTO STUDIO / 01',75,75);const pic=document.createElement('canvas');pic.width=1536;pic.height=1360;draw(pic.getContext('2d'),{photo:true,choice:state.choice});g.drawImage(pic,75,110,1050,930);g.font='36px system-ui';g.fillText(state.choice==='space'?'누구든 앉다 갈 수 있던 자리':'다음 오후에도, 빛이 드는 곳에서',75,1135);g.font='23px system-ui';g.fillText('미나미 사진관 · 빈자리의 주인',75,1200);g.fillStyle='#7c8271';g.font='20px system-ui';g.fillText('철거되는 건 가게지만, 사진관은 계속될 거예요.',75,1305);return out.toDataURL('image/jpeg',.92);}
function moveChair(x){if(anim)cancelAnimationFrame(anim);const from=chairVisual;if(!dispatch({type:'chair',x}))return;const to=state.chair;if(reduced){chairVisual=to;draw(c);return;}const start=performance.now();function tick(now){const p=Math.min(1,(now-start)/420);chairVisual=from+(to-from)*(1-Math.pow(1-p,3));draw(c);positionTargets();if(p<1)anim=requestAnimationFrame(tick);else{anim=0;if(compareOpen)drawCompare();}}anim=requestAnimationFrame(tick);say(to<=710?'의자 아래에 봉투가 있었어요. 바닥도 살펴볼까요?':'의자를 다시 옮겼어요.');}
function object(type){if(type==='chair')moveChair(state.chair>710?560:870);if(type==='lamp'){dispatch({type:'lamp'});say(state.lamp?'스탠드의 빛이 바닥의 작은 자국을 비춰요.':'스탠드를 껐어요.');}if(type==='letter')inspectLetter();if(type==='mark')inspectMark();}
function positionTargets(){const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/1536,r.height/1360),ox=(r.width-1536*scale)/2,oy=(r.height-1360*scale)/2;for(const b of $('targets').querySelectorAll('[data-object]')){const p={chair:[chairVisual+155,1080],lamp:[440,455],letter:[975,1190],mark:[1150,1260]}[b.dataset.object];b.style.left=(ox+p[0]*scale)+'px';b.style.top=(oy+p[1]*scale)+'px';b.style.color='#fff8e8';b.style.background='#344b4088';b.textContent={chair:'의자',lamp:'빛',letter:'편지',mark:'흔적'}[b.dataset.object];}}
addEventListener('resize',()=>positionTargets());
function point(e,el=canvas){const r=el.getBoundingClientRect(),scale=Math.min(r.width/1536,r.height/1360),ox=(r.width-1536*scale)/2,oy=(r.height-1360*scale)/2;return{x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale};}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0||!assets.room)return;const p=point(e);if(p.x>=chairVisual+35&&p.x<=chairVisual+285&&p.y>950&&p.y<1245){if(anim)cancelAnimationFrame(anim);drag={id:e.pointerId,start:p.x,x:chairVisual,moved:false};canvas.setPointerCapture(e.pointerId);}});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=point(e);if(Math.abs(p.x-drag.start)>12)drag.moved=true;chairVisual=Math.max(560,Math.min(1000,drag.x+p.x-drag.start));draw(c);positionTargets();});
canvas.addEventListener('pointerup',e=>{if(drag?.id===e.pointerId){const d=drag;drag=null;if(d.moved){dispatch({type:'chair',x:chairVisual});say('의자를 옮겼어요. 아래에 무엇이 남았을까요?');}else object('chair');return;}const p=point(e);if(p.x>360&&p.x<510&&p.y>370&&p.y<610)object('lamp');else if(Math.abs(p.x-975)<90&&Math.abs(p.y-1190)<65)object('letter');else if(p.x>1030&&p.x<1290&&p.y>1180&&p.y<1320)object('mark');});
function cancelDrag(){if(drag){drag=null;chairVisual=state.chair;draw(c);}}canvas.addEventListener('pointercancel',cancelDrag);canvas.addEventListener('lostpointercapture',cancelDrag);
$('compare').onclick=()=>{compareOpen=true;$('comparison').hidden=false;drawCompare();$('align').focus();};$('compare-close').onclick=()=>{compareOpen=false;$('comparison').hidden=true;$('compare').focus();};$('align').oninput=e=>{offset=Number(e.target.value);drawCompare();};$('match').onclick=()=>{if(dispatch({type:'align',offset:offset/1536})){offset=0;$('align').value=0;drawCompare();say('옛 사진 속에는 의자가 두 개예요. 사진 뒷면에도 기록이 있어요.');}};
let compDrag=null;$('compare-view').addEventListener('pointerdown',e=>{if(e.button!==0)return;compDrag={id:e.pointerId,x:e.clientX,offset};e.currentTarget.setPointerCapture(e.pointerId);});$('compare-view').addEventListener('pointermove',e=>{if(compDrag?.id!==e.pointerId)return;offset=Math.max(-180,Math.min(180,compDrag.offset+(e.clientX-compDrag.x)*1536/e.currentTarget.clientWidth));$('align').value=offset;drawCompare();});for(const name of ['pointerup','pointercancel','lostpointercapture'])$('compare-view').addEventListener(name,()=>{compDrag=null;});
$('back-photo').onclick=inspectBack;$('move-chair').onclick=()=>object('chair');$('lamp').onclick=()=>object('lamp');$('read-letter').onclick=inspectLetter;$('read-mark').onclick=inspectMark;$('journal').onclick=()=>journal();$('camera').onclick=camera;
$('help').onclick=()=>{const text=caseHint(state,hint),phase=caseHint(state,0);if(phase!==lastHint){hint=0;lastHint=phase;}show('조금만 다른 곳을 볼까요?',`<p>${caseHint(state,hint)}</p><div class="actions"><button data-action="hint-more">${hint<2?'조금 더 구체적으로':'처음 힌트부터'}</button><button class="primary" data-action="close">직접 해볼게요</button></div>`);};
$('detail-toggle').onclick=()=>{$('targets').hidden=!$('targets').hidden;positionTargets();$('detail-toggle').textContent=$('targets').hidden?'사물 위치 보기':'사물 위치 숨기기';};$('targets').onclick=e=>{const b=e.target.closest('[data-object]');if(b)object(b.dataset.object);};
$('sheet').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.answer){const ok=dispatch({type:'answer',answer:b.dataset.answer});journal(ok?'':'아직 이 해석을 뒷받침하는 흔적이 없어요. 여러 편지의 보낸 사람을 비교해 보세요.');return;}if(b.dataset.choice){dispatch({type:'choose',choice:b.dataset.choice});camera();return;}switch(b.dataset.action){case'close':close();break;case'start':dispatch({type:'start'});close();say('먼저 옛 사진을 지금 가게에 겹쳐 볼까요?');break;case'journal':journal();break;case'camera':camera();break;case'shoot':if(dispatch({type:'shoot'})){chairVisual=state.choice==='space'?590:1000;draw(c);ending();}break;case'hint-more':hint=(hint+1)%3;$('help').click();break;case'replay':show('다른 구도로 남겨 볼까요?',`<p>모은 기록은 남겨 두고 마지막 촬영만 다시 선택해요. 이전 사진책은 저장해 두면 간직할 수 있어요.</p><div class="actions"><button class="primary" data-action="rechoose">구도 다시 고르기</button><button data-action="close">그대로 둘게요</button></div>`);break;case'rechoose':state={...state,shot:false,choice:null};try{localStorage.setItem(CASE_SAVE,JSON.stringify(state));}catch{storage=false;}chairVisual=state.chair;update();camera();break;}});
document.addEventListener('keydown',e=>{if($('modal').hidden){if(e.key==='Escape'&&compareOpen)$('compare-close').click();return;}if(e.key==='Escape'&&state.started)close();if(e.key==='Tab'){const f=[...$('sheet').querySelectorAll('button,a[href],input')].filter(e=>!e.disabled);if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});
try{assets=Object.fromEntries(await Promise.all([['room','travel-art/tokyo-clear-v12.webp'],['chair','travel-art/chair-v82.webp']].map(async([k,url])=>{const img=new Image();img.src=url;await img.decode();return[k,img];})));if(state.shot)chairVisual=state.choice==='space'?590:1000;update();if(!state.started)show('내일, 마지막 한 장.',`<p class="serif">내일, 이 가게의 마지막 한 컷.</p><div class="note">“아버지 사진관이 새 작업실로 이사해요.<br>철거 전에 마지막 모습을 남기고 싶어요.<br>이 사진 속 자리에서 찍어 주실래요?”<br><small>— 하루</small></div><p>사진에는 두 개의 의자가 있어요.<br>지금 가게에는 하나만 남아 있네요.</p><div class="actions"><button class="primary" data-action="start">의뢰 봉투 열기</button></div><p class="journal-note">첫 의뢰 체험 · 마우스와 터치 모두 가능<br>의자는 직접 끌거나 아래 도구로 옮길 수 있어요.</p>`,{closable:false});else if(state.shot)say('완성한 사진책을 다시 열거나 가게에 머물 수 있어요.');}catch{show('가게 사진을 불러오지 못했어요',`<p>연결을 확인하고 다시 열어 주세요. 이전 진행은 그대로 남아 있어요.</p><div class="actions"><button data-action="reload" onclick="location.reload()">다시 불러오기</button></div>`);}
